
/* Rediseño visual UAM: capa CSS, sin alterar la lógica funcional */
:root{--uam-cyan:#12d8ee;--uam-blue:#0d6fb8;--uam-deep:#031934;--uam-ink:#0d2b59;--uam-soft:var(--route-legacy-surface, #f6f9fe);--uam-border:#dbe7f4}
body{background:var(--route-legacy-surface, #f5f8fd);color:#10233f}
.app{grid-template-columns:310px minmax(0,1fr);background:var(--route-legacy-surface, #f7faff)}
.sidebar{background:linear-gradient(180deg,#02152d 0%,#042442 62%,#031a33 100%)!important;padding:24px 18px 22px;gap:18px;border-right:1px solid rgba(25,219,255,.13);box-shadow:inset -1px 0 rgba(255,255,255,.03);position:sticky}
.uam-brand{display:block!important;padding:6px 8px 22px!important;border-bottom:1px solid rgba(255,255,255,.1);text-align:center}
.uam-wordmark strong{display:block;font-size:68px;line-height:.9;letter-spacing:-.08em;color:#fff;font-weight:900}
.uam-wordmark span{display:block;margin-top:10px;color:#fff;font-size:11px;font-weight:800;line-height:1.35;letter-spacing:.17em}
.sidebar-profile{background:transparent!important;border:0!important;border-radius:0!important;padding:14px 5px 18px!important;border-bottom:1px solid rgba(255,255,255,.08)!important;box-shadow:none!important}
.sidebar-profile-main{gap:14px!important}.profile-avatar-wrap,.profile-avatar,.profile-avatar-fallback{width:62px!important;height:62px!important;min-width:62px!important;min-height:62px!important;border-radius:50%!important}
.profile-avatar,.profile-avatar-fallback{border:3px solid var(--route-legacy-line, rgba(24,223,249,.72))!important;box-shadow:0 0 0 4px rgba(255,255,255,.05),0 12px 26px rgba(0,0,0,.25)!important}
.profile-avatar-fallback{background:linear-gradient(135deg,#0f76b8,var(--route-legacy-soft, #10d4ee))!important;color:#fff!important;font-size:20px!important}
.profile-avatar-edit{background:var(--route-legacy-soft, #12d8ee)!important;color:#053251!important;border:2px solid #041d38!important}
.profile-copy b{font-size:16px!important;color:#fff!important}.profile-copy small{font-size:11.5px!important;color:#b7c8da!important;white-space:normal!important}
.profile-edit-button{margin-top:9px!important;height:34px!important;border:1px solid rgba(255,255,255,.1)!important;background:rgba(255,255,255,.04)!important;border-radius:10px!important;color:#d8e7f5!important;padding:0 11px!important}
.nav{gap:6px!important}.nav-label{font-size:10px!important;letter-spacing:.2em!important;color:#8ea9c3!important;padding:6px 10px 2px!important;margin:0!important}.nav button{min-height:48px;padding:0 13px!important;border-radius:13px!important;font-size:14.5px!important;font-weight:600!important;color:#dce9f5!important}.nav button .ic{width:19px;height:19px}.nav button:hover{background:rgba(255,255,255,.07)!important;color:#fff!important}.nav button.on{background:linear-gradient(90deg,rgba(9,123,194,.5),rgba(21,113,184,.3))!important;color:#fff!important;box-shadow:inset 3px 0 0 var(--uam-cyan),inset 0 0 0 1px rgba(18,216,238,.11),0 10px 24px rgba(0,0,0,.18)!important}
.side-card{background:rgba(255,255,255,.045)!important;border:1px solid rgba(255,255,255,.08)!important;border-radius:16px!important}.side-actions button{border-radius:10px!important}.side-actions button:hover{background:rgba(255,255,255,.07)!important}
main{background:var(--route-legacy-surface, #f7faff)}
.topbar{padding:18px 26px 13px!important;background:var(--route-legacy-surface, #f7faff)!important;border-bottom:0!important;backdrop-filter:none!important;align-items:flex-start!important}.topbar-kicker{font-size:12px!important;color:#7183a2!important}.live-dot{background:#254a7a!important;box-shadow:none!important}.topbar h1{font-size:40px!important;line-height:1!important;color:#102d5b!important;letter-spacing:-.045em!important;margin-top:5px}.topbar p{font-size:13.5px!important;color:#607596!important;max-width:850px}.topbar-right{gap:10px!important;align-items:center!important}.global-search-btn{height:48px!important;min-width:350px!important;justify-content:flex-start!important;border-radius:15px!important;border:1px solid var(--route-legacy-line, #d8e5f3)!important;background:var(--route-legacy-surface, #fff)!important;color:#526989!important;box-shadow:0 10px 26px rgba(18,42,84,.07)!important}.global-search-btn span{display:inline!important}.global-search-btn kbd{margin-left:auto!important;background:var(--route-legacy-soft, #eef4fb)!important;border:0!important;color:#36567f!important}.top-stats{gap:5px!important}.top-stats div{border-radius:13px!important;border-color:var(--route-legacy-line, #dbe7f4)!important;box-shadow:0 8px 20px rgba(18,42,84,.05)!important}.view{padding:8px 22px 56px!important}
.hero{grid-template-columns:minmax(0,1.02fr) minmax(320px,.9fr)!important;min-height:404px;padding:26px 30px 22px!important;border-radius:22px!important;background:linear-gradient(90deg,rgba(3,18,42,1) 0%,rgba(3,18,42,.98) 14%,rgba(3,18,42,.86) 23%,rgba(3,18,42,.52) 31%,rgba(3,18,42,.2) 38%,rgba(3,18,42,.05) 44%,rgba(3,18,42,0) 49%),url('data:image/png;base64,')!important;background-size:cover,100% auto!important;background-position:center center,55% center!important;background-repeat:no-repeat!important;box-shadow:0 22px 50px rgba(5,31,67,.18)!important;isolation:isolate;overflow:hidden}.hero::before{display:none!important}.hero::after{content:'';position:absolute;inset:0;background-image:linear-gradient(rgba(255,255,255,.04) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.04) 1px,transparent 1px);background-size:32px 32px;mask-image:linear-gradient(90deg,transparent 34%,#000);opacity:.22;z-index:-1;pointer-events:none}.hero-text{gap:10px!important;position:relative;z-index:2;max-width:610px}.eyebrow{border:0!important;background:transparent!important;padding:0!important;text-transform:uppercase;letter-spacing:.17em!important;font-size:10.5px!important;color:#d9f8ff!important}.hero h2{font-size:44px!important;line-height:.94!important;max-width:9.6ch;letter-spacing:-.055em!important}.hero p{font-size:14px!important;line-height:1.46!important;max-width:500px!important;color:#dcebf8!important}.hero .btn.light{background:var(--uam-cyan)!important;color:#032747!important;height:48px!important;border-radius:12px!important;padding:0 21px!important;box-shadow:0 12px 28px rgba(18,216,238,.26)!important}.hero .btn.outline-light{height:48px!important;border-radius:12px!important;border:2px solid var(--route-legacy-line, rgba(255,255,255,.45))!important;padding:0 21px!important}.hero-dashboard{align-self:end!important;background:rgba(2,23,50,.82)!important;border:1px solid rgba(134,235,255,.28)!important;border-radius:18px!important;backdrop-filter:blur(7px)!important;box-shadow:0 18px 36px rgba(0,0,0,.18)!important;position:relative;z-index:2}.hero-dash-top,.hero-progress,.hero-mini-grid>div{color:#fff!important}.hero-status{background:rgba(18,216,238,.13)!important;color:#9df4ff!important}.hero-status i{background:var(--route-legacy-soft, #20e0f4)!important}.hero-bar{background:rgba(255,255,255,.15)!important}.hero-bar i{background:linear-gradient(90deg,var(--route-legacy-soft, #13d9ef),var(--route-legacy-soft, #7cf4ff))!important}.hero-mini-grid{gap:8px!important}.hero-mini-grid>div{background:rgba(255,255,255,.08)!important;border:1px solid rgba(255,255,255,.08)!important;border-radius:12px!important}
.hero-proof{grid-column:1/-1;display:grid!important;grid-template-columns:repeat(4,1fr)!important;gap:14px!important;margin-top:16px!important;background:transparent!important;border:0!important;padding:0!important}.hero-proof span{display:flex!important;align-items:center!important;gap:12px!important;min-height:68px!important;padding:12px 14px!important;border-radius:15px!important;background:var(--route-legacy-surface, #fff)!important;border:1px solid var(--route-legacy-line, #dbe7f4)!important;color:#173761!important;font-weight:750!important;box-shadow:0 8px 24px rgba(20,51,95,.08)!important}.hero-proof span .ic{width:32px!important;height:32px!important;padding:7px;border-radius:10px;background:linear-gradient(135deg,#16b9ce,#167ed0);color:#fff!important}
.section-heading{margin-top:20px!important}.section-heading h3{font-size:23px!important;color:#143260!important}.section-heading p{color:#6c809e!important}.section-kicker{width:38px;height:3px;overflow:hidden;color:transparent!important;background:#0fbfd9;border-radius:999px;margin-bottom:8px}.mini-note{color:#7d8ea8!important}.slots{gap:18px!important;margin-top:8px!important}.slot{min-height:250px!important;border-radius:20px!important;border:1px solid var(--route-legacy-line, #d8e5f2)!important;box-shadow:0 10px 30px rgba(18,42,84,.07)!important;padding:17px!important}.slot-num{width:42px!important;height:42px!important;border-radius:999px!important;background:linear-gradient(135deg,#0d5a9a,#153f7b)!important}.slot-name{font-size:18px!important;color:#18355e!important}.drop{border-radius:16px!important;border-color:var(--route-legacy-line, #c4d9ef)!important;background:var(--route-legacy-surface, #f8fbff)!important;min-height:150px!important}.drop-ic{width:54px!important;height:54px!important;border-radius:16px!important;background:linear-gradient(135deg,#2062dc,#1a87e4)!important}.drop b{color:#18396a!important}.slot-alt .link{color:#1f5ed0!important}.dashboard-university{grid-template-columns:1.3fr .7fr!important;gap:18px!important;margin-top:18px!important}.dash-mini{border-radius:20px!important;border:1px solid var(--route-legacy-line, #d9e5f2)!important;box-shadow:0 10px 28px rgba(17,44,86,.07)!important;padding:20px!important;background:var(--route-legacy-surface, #fff)!important}.dash-mini-head h4{color:#173762!important}.dash-mini-head button{color:#6234d9!important;font-weight:800!important}.week-focus-number{color:#5b31c8!important}.quick-tool{background:var(--route-legacy-soft, #f4effb)!important;color:#5b31c8!important;border-radius:15px!important}
.curriculum-hero,.panel,.table-wrap,.kpi,.sem,.req-map-panel,.grad-hero,.agenda-shell .agenda-sidebar,.agenda-shell .agenda-main,.study-shell,.grade-sem-card{border-color:var(--route-legacy-line, #d9e5f2)!important;box-shadow:0 10px 28px rgba(17,44,86,.06)!important}
@media(max-width:1280px){.app{grid-template-columns:275px minmax(0,1fr)}.global-search-btn{min-width:260px!important}.hero h2{font-size:40px!important}.hero{grid-template-columns:1fr!important;background-position:center center,53% center!important;background-size:cover,104% auto!important}.hero-dashboard{max-width:430px}.hero-proof{grid-template-columns:repeat(2,1fr)!important}.dashboard-university{grid-template-columns:1fr!important}}
@media(max-width:900px){.app{grid-template-columns:1fr}.topbar{padding:14px 14px 8px!important}.topbar h1{font-size:32px!important}.view{padding:8px 14px 90px!important}.global-search-btn{min-width:0!important}.hero{padding:24px 18px!important;min-height:0;background-position:center center,52% center!important;background-size:cover,118% auto!important}.hero h2{font-size:36px!important;max-width:10.5ch}.hero-proof{grid-template-columns:1fr!important}.slots{grid-template-columns:1fr!important}.dashboard-university{grid-template-columns:1fr!important}}
@media(max-width:520px){.topbar-right{width:100%!important}.global-search-btn{width:44px!important;height:44px!important;padding:0!important;justify-content:center!important}.global-search-btn span,.global-search-btn kbd{display:none!important}.hero h2{font-size:30px!important}.uam-wordmark strong{font-size:54px}.sidebar-profile{padding-top:8px!important}.hero{background-position:center center,49% center!important;background-size:cover,138% auto!important}.hero-dashboard{width:100%}}
/* Corrección responsive: el sidebar fuera de pantalla no debe ocupar una fila del grid. */
@media(max-width:900px){
  .sidebar{position:fixed!important;top:0!important;left:0!important;bottom:0;z-index:70!important;transform:translateX(-105%);}
  body.menu-open .sidebar{transform:translateX(0)!important;}
  .app{display:grid!important;grid-template-columns:minmax(0,1fr)!important;}
  .app > main{grid-column:1!important;grid-row:1!important;min-width:0;}
}
